import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { fetchProducts, deleteProduct, type Product } from '../lib/api';

const formatPrice = (price: number): string => {
  return price.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

export default function AdminProductsPage() {
  const navigate = useNavigate();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  const loadProducts = () => {
    setLoading(true);
    fetchProducts()
      .then(res => setProducts(res.data || []))
      .catch(() => setProducts([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => { loadProducts(); }, []);

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(`Hapus "${name}" dari inventaris?`)) return;
    try {
      await deleteProduct(id);
      loadProducts();
    } catch (err: unknown) {
      alert(`Gagal menghapus: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  };

  return (
    <main className="p-4 sm:p-8 lg:p-12 animate-in fade-in duration-500 font-body">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-12">
        <div>
          <h2 className="text-3xl md:text-4xl font-extrabold font-headline tracking-tight text-on-surface">Manajemen Inventaris</h2>
          <p className="text-on-surface-variant mt-2 text-sm md:text-base">Kelola stok dan visibilitas koleksi kartu Ajambeh.</p>
        </div>
        <div className="flex flex-wrap gap-4 w-full md:w-auto">
          <button
            onClick={() => navigate('/admin/product/add')}
            className="flex-1 md:flex-none justify-center bg-gradient-to-r from-primary to-primary-container text-on-primary-container px-6 py-3 rounded-full font-bold hover:scale-105 transition-transform shadow-lg shadow-primary/20 flex items-center gap-2 text-sm md:text-base"
          >
            <span className="material-symbols-outlined">add</span>
            Tambah Produk
          </button>
        </div>
      </header>

      <section className="bg-surface-container-low rounded-lg overflow-hidden border border-outline-variant/10">
        <div className="p-4 sm:p-6 border-b border-outline-variant/10 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <h3 className="text-xl font-bold font-headline">Daftar Produk</h3>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left whitespace-nowrap">
            <thead className="bg-surface-container-lowest text-on-surface-variant uppercase text-[10px] tracking-[0.2em] font-bold">
              <tr>
                <th className="px-6 lg:px-8 py-4">Foto</th>
                <th className="px-6 lg:px-8 py-4">Nama Produk</th>
                <th className="px-6 lg:px-8 py-4 text-right">Harga</th>
                <th className="px-6 lg:px-8 py-4 text-center">Stok</th>
                <th className="px-6 lg:px-8 py-4 text-center">Status</th>
                <th className="px-6 lg:px-8 py-4 text-center">Visible</th>
                <th className="px-6 lg:px-8 py-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-outline-variant/10">
              {loading && (
                <tr><td colSpan={7} className="text-center py-12 text-on-surface-variant animate-pulse">Memuat produk...</td></tr>
              )}
              {!loading && products.length === 0 && (
                <tr><td colSpan={7} className="text-center py-12 text-on-surface-variant">Belum ada produk. Klik "Tambah Produk" untuk memulai.</td></tr>
              )}
              {products.map(product => {
                const primaryImage = product.images?.find(i => i.is_primary) || product.images?.[0];
                const isOutOfStock = product.stock === 0;
                return (
                  <tr key={product.id} className="hover:bg-surface-bright/40 transition-colors group">
                    <td className="px-6 lg:px-8 py-4 lg:py-6">
                      <div className={`w-12 h-16 lg:w-16 lg:h-20 rounded-md overflow-hidden bg-surface-container-high border border-primary/10 ${isOutOfStock ? 'grayscale opacity-50' : ''}`}>
                        {primaryImage ? (
                          <img alt={product.name} className="w-full h-full object-cover" src={primaryImage.url} />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center">
                            <span className="material-symbols-outlined text-on-surface-variant/30">image</span>
                          </div>
                        )}
                      </div>
                    </td>
                    <td className={`px-6 lg:px-8 py-4 lg:py-6 ${isOutOfStock ? 'opacity-50' : ''}`}>
                      <p className="font-bold group-hover:text-primary transition-colors text-white">{product.name}</p>
                      <p className="text-xs text-on-surface-variant mt-0.5">
                        {product.condition?.name || ''} · {product.categories?.map(c => c.name).join(', ') || 'No category'}
                      </p>
                    </td>
                    <td className="px-6 lg:px-8 py-4 lg:py-6 text-right">
                      <span className="font-bold text-primary">Rp {formatPrice(product.price)}</span>
                    </td>
                    <td className="px-6 lg:px-8 py-4 lg:py-6 text-center">
                      <span className={`font-bold ${isOutOfStock ? 'text-on-surface-variant/40' : product.stock <= 3 ? 'text-secondary' : 'text-on-surface'}`}>{product.stock}</span>
                    </td>
                    <td className="px-6 lg:px-8 py-4 lg:py-6 text-center">
                      {isOutOfStock ? (
                        <span className="px-3 py-1 bg-surface-container-highest text-on-surface-variant/40 text-[10px] font-bold rounded-full uppercase tracking-wider">Out of Stock</span>
                      ) : product.stock <= 3 ? (
                        <span className="px-3 py-1 bg-secondary/10 text-secondary text-[10px] font-bold rounded-full uppercase tracking-wider">Warning</span>
                      ) : (
                        <span className="px-3 py-1 bg-primary/10 text-primary text-[10px] font-bold rounded-full uppercase tracking-wider">Available</span>
                      )}
                    </td>
                    <td className="px-6 lg:px-8 py-4 lg:py-6 text-center">
                      {product.is_published ? (
                        <span className="material-symbols-outlined text-primary" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                      ) : (
                        <span className="material-symbols-outlined text-on-surface-variant/30">cancel</span>
                      )}
                    </td>
                    <td className="px-6 lg:px-8 py-4 lg:py-6 text-right">
                      <div className="flex justify-end gap-1">
                        <button onClick={() => navigate(`/admin/product/edit/${product.id}`)} className="p-2 hover:bg-surface-container-highest rounded-full transition-colors text-on-surface-variant hover:text-primary">
                          <span className="material-symbols-outlined text-lg">edit</span>
                        </button>
                        <button onClick={() => handleDelete(product.id, product.name)} className="p-2 hover:bg-surface-container-highest rounded-full transition-colors text-on-surface-variant hover:text-secondary">
                          <span className="material-symbols-outlined text-lg">delete</span>
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="px-4 sm:px-6 lg:px-8 py-4 lg:py-6 border-t border-outline-variant/10 text-on-surface-variant text-sm">
          <span>Menampilkan {products.length} Produk</span>
        </div>
      </section>
    </main>
  );
}
